import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.TQKaXlFR.js";const u=JSON.parse('{"title":"能力与边界","description":"","frontmatter":{},"headers":[],"relativePath":"overview/capabilities.md","filePath":"overview/capabilities.md"}'),o={name:"overview/capabilities.md"};function l(i,t,c,h,s,n){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="能力与边界" tabindex="-1">能力与边界 <a class="header-anchor" href="#能力与边界" aria-label="Permalink to &quot;能力与边界&quot;">​</a></h1><h2 id="怎样使用这份清单" tabindex="-1">怎样使用这份清单 <a class="header-anchor" href="#怎样使用这份清单" aria-label="Permalink to &quot;怎样使用这份清单&quot;">​</a></h2><p>本页帮助管理人员和开发者判断当前功能是否覆盖自己的需求。前提是按<a href="./../guide/configuration.html">运行配置</a>完成部署，并使用相应身份和操作权限。代码已实现、本地功能已验证、外部供应商已接通、正式发行可用是不同状态。</p><p>下表对应<a href="./../releases/versions.html">当前源码配对</a>，包含已经验收的AI一期。v1.2.0已发布静态旧快照与当前未打独立Tag的AI源码分别记录。清单不承诺所有角色都能访问，也不把后端依赖或配置项当成已完成的产品功能。</p><h2 id="已有功能入口" tabindex="-1">已有功能入口 <a class="header-anchor" href="#已有功能入口" aria-label="Permalink to &quot;已有功能入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>实际能力</th><th>操作入口与限制</th></tr></thead><tbody><tr><td>系统管理</td><td>用户、角色、菜单</td><td><a href="./../features/accounts.html">账号</a>、<a href="./../features/authorization.html">授权</a>、<a href="./../features/menus.html">菜单</a>；没有新增部门/岗位模型</td></tr><tr><td>系统管理</td><td>字典管理、系统参数</td><td><a href="./../features/dictionary.html">字典</a>、<a href="./../features/parameters.html">参数</a>；编码和值的不可修改规则见页面操作说明</td></tr><tr><td>系统管理</td><td>系统业务配置</td><td><a href="./../features/business-config.html">微信、SMS、OSS单页配置</a>；服务端要求平台身份和对应操作权限</td></tr><tr><td>通用能力</td><td>文件管理</td><td><a href="./../features/files.html">文件</a>；对象存储必须显式配置，关闭时不能假定上传可用</td></tr><tr><td>通用能力（旧链路兼容）</td><td>模型元数据、场景提示词与变量</td><td><a href="./../features/ai.html">AI</a>；保留旧appKey/sceneKey读取与数据，不自动转换为新应用绑定</td></tr><tr><td>AI管理</td><td>独立AI配置、提示词与调用监控</td><td><a href="./../features/ai.html">AI实用流程</a>；已实现命名多Key关联多模型、OpenRouter/DeepSeek官方预设与目录扫描、多渠道备用及完整对话；原生核对已覆盖扫描、加密保存/刷新、多渠道优先级、单行/整表/关联子行预览与引用保存。目录不等于生成验证，DeepSeek无真实Key联调，管理权不替代业务读取与调用权</td></tr><tr><td>低代码记录入口</td><td>AI摘要、人工采纳保存</td><td><a href="./../features/lowcode.html">低代码</a>；历史一期配对已验收模型到SSE、草稿采纳及保存刷新；本轮两次OpenRouter原生摘要均超时，生成到采纳保存的正向实测尚未完成，不是Agent自动写入</td></tr><tr><td>通用能力</td><td>通知公告、通知模板、个人收件箱</td><td><a href="./../features/notifications.html">通知</a>；本人收件箱不授予全局模板/配置管理权</td></tr><tr><td>通用能力</td><td>低代码表单</td><td><a href="./../features/lowcode.html">表单</a>；平台设计/发布，授权记录操作和数据范围仍由服务端限制</td></tr><tr><td>通用能力</td><td>资讯管理</td><td><a href="./../features/news.html">资讯</a>；保留当前实现，其他网站内容模块已退役</td></tr><tr><td>运行维护</td><td>受控定时任务、调度日志、操作日志</td><td><a href="./../features/scheduler.html">调度</a>；处理器受控，不能配置任意类或脚本执行</td></tr><tr><td>运行维护</td><td>工作台、看板</td><td>已有前端页面；不能把演示图表解释为真实业务分析数据</td></tr><tr><td>用户页面操作</td><td><code>.xlsx</code>导入、模板与导出</td><td><a href="./../features/bulk.html">导入导出</a>；导入最多1000行/5 MiB，新账号待激活，密码不回显</td></tr></tbody></table><p>低代码当前支持 <code>text</code>、<code>textarea</code>、<code>number</code>、<code>date</code>、<code>select</code>、<code>multiselect</code>、<code>switch</code> 七种字段，草稿与发布版本分开，记录带版本与 revision。未实现联动表达式、附件字段、匿名公开填写或动态生成数据库表。具体字段契约见<a href="./../development/lowcode-extension.html">表单扩展</a>。</p><h2 id="身份与租户边界" tabindex="-1">身份与租户边界 <a class="header-anchor" href="#身份与租户边界" aria-label="Permalink to &quot;身份与租户边界&quot;">​</a></h2><p>配置类能力不仅检查按钮操作码，也检查平台身份。后端 <code>tenant.enable</code> 默认 <code>false</code>；启用租户后，不应推断租户用户能够读取全局配置。菜单响应会过滤平台能力，API仍独立检查。前端“隐藏按钮”不能替代授权。</p><p>普通登录用户的个人收件箱使用已认证路由和本人通知接口；即使没有通用业务配置菜单，前端可生成只含个人收件箱的通用组。低代码填写/记录操作也不等于取得表单设计权限。细节见<a href="./../development/tenant-platform.html">租户与平台</a>。</p><h2 id="需要另行验证的外部能力" tabindex="-1">需要另行验证的外部能力 <a class="header-anchor" href="#需要另行验证的外部能力" aria-label="Permalink to &quot;需要另行验证的外部能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>当前事实</th><th>接入前的动作</th></tr></thead><tbody><tr><td>PC网站微信扫码</td><td>已交付配置、PC授权发起与state校验；真实身份扫码受应用资质与回调条件限制。WX02账号绑定、WX03登录尚未交付</td><td>按<a href="./../features/business-config.html">业务配置</a>准备合法网站应用及回调，不用公众号测试号代替网站应用，不把授权发起视为绑定或登录成功</td></tr><tr><td>SMS</td><td>配置与适配存在；真实供应商发送未作为全部部署的已验证能力</td><td>配置自己的供应商及模板，控制真实发送测试</td></tr><tr><td>对象存储</td><td>显式启用后执行文件链路；本地验证不能保证你的存储端点可达</td><td>设置独立凭据/桶，按<a href="./../features/files.html">文件手册</a>验证上传、读取与恢复</td></tr><tr><td>AI模型与业务调用</td><td>历史一期配对有真实模型测试与摘要闭环；本轮普通持久对话已成功两轮并保存四条消息，原生低代码摘要两次上游超时，正向生成到采纳保存仍待实测</td><td>分别核对场景与源码配对，普通对话不替代摘要验证；保留限流/超时等真实结果，不保证全部或免费模型持续可用</td></tr><tr><td>质量与发行</td><td>本轮源码功能及上述原生检查已有确认，未新增版本标签；历史配对的正式CI和MySQL服务矩阵证据按原范围保留</td><td>当前CI、最终源码配对及Pages部署以目标Git分支、publication.json和实际结果分别核对；本轮低代码摘要正向实测仍待完成</td></tr></tbody></table><h2 id="不在当前交付范围" tabindex="-1">不在当前交付范围 <a class="header-anchor" href="#不在当前交付范围" aria-label="Permalink to &quot;不在当前交付范围&quot;">​</a></h2><p>工作流、报表设计、组织权限管理器、通用代码生成器、分片断点续传、模型计费平台、Agent、插件执行和知识库不是当前已交付能力。一期已具备通过测试的多Key准入及应用策略范围内的选择/备用，不应再列为全部未实现；它也不等于通用网关或独立计费配额平台。两个独立业务系统真实采用尚未验证。资料示例、网站五模块、下载管理、页面管理已删除，不作为扩展示范恢复。</p><h2 id="正常判断与失败恢复" tabindex="-1">正常判断与失败恢复 <a class="header-anchor" href="#正常判断与失败恢复" aria-label="Permalink to &quot;正常判断与失败恢复&quot;">​</a></h2><p>选一个需求，先读对应功能操作，再核对<a href="./../reference/api-catalog.html">API目录</a>和<a href="./../components/overview.html">组件参考</a>。能找到实际路由、权限检查和服务代码，才把它作为已有能力使用。</p><p>出现403应检查身份和授权，不能清空缓存绕过；外部服务未配置或429不是页面保存必然失败；没有找到对应源码时将其视为建设需求，不凭本页相近词汇判断已实现。错误处理见<a href="./../reference/error-codes.html">错误与恢复</a>。</p><h2 id="实际源码来源" tabindex="-1">实际源码来源 <a class="header-anchor" href="#实际源码来源" aria-label="Permalink to &quot;实际源码来源&quot;">​</a></h2><ul><li>后端 <code>system-admin/src/main/java/com/xinghuiTec/security/PlatformVisibilityService.java</code>：平台菜单/权限过滤。</li><li>后端同模块 <code>controller/BusinessConfigController.java</code>、<code>AiModelTestController.java</code>、<code>NotificationInboxController.java</code>：配置/模型/本人通知边界。</li><li>后端同模块 <code>lowcode/LowcodeSchema.java</code>：<code>TYPES</code>、字段校验；<code>LowcodeFormController.java</code>、<code>LowcodeRecordController.java</code>：设计与记录权限。</li><li>后端同模块 <code>controller/ContentNewsController.java</code>：保留资讯接口。</li><li>前端 <code>apps/web-ele/src/views/system/user/index.vue</code>：导入限制与待激活提示。</li><li>前端 <code>apps/web-ele/src/router/routes-helper.ts</code>、<code>router/routes/modules/lowcode.ts</code>：个人入口与隐藏运行页。</li></ul>',19)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
